import { Constants, ConstantValue, StudioProApi } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";

export const handleShowConstant = async (studioPro: StudioProApi, modelDocument: ModelDocument): Promise<void> => {
    const constant = await getConstantById(studioPro, modelDocument.documentId);

    if (!constant) {
        const errorMessage = "Could not find constant.";
        const errorDetails =
            "This constant might have been deleted or renamed. Please update the tool constant selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    await studioPro.ui.editors.editDocument(constant.$ID);
};

export const getConstantDefaultValue = (constant?: Constants.Constant): string | undefined => {
    if (!constant) {
        return;
    }

    return constant.defaultValue;
};

export const getRuntimeConstantByQualifiedName = async (
    studioPro: StudioProApi,
    constantQualifiedName: string
): Promise<ConstantValue | undefined> => {
    // Fetch all constant values from the runtime configuration and find the one matching the qualified name
    const runtimeConstantValues = await studioPro.runtime.configuration.getConstants();
    const constant = runtimeConstantValues.find((value) => value.constantName === constantQualifiedName);
    return constant;
};

export const getConstantValue = async (
    studioPro: StudioProApi,
    modelDocument?: ModelDocument
): Promise<string | undefined> => {
    if (!modelDocument) {
        return;
    }

    const runtimeConstant = await getRuntimeConstantByQualifiedName(studioPro, modelDocument.qualifiedName);
    const constant = await getConstantById(studioPro, modelDocument.documentId);
    const defaultValue = getConstantDefaultValue(constant);

    if (!runtimeConstant) {
        return defaultValue;
    }

    if (runtimeConstant.status === "private") {
        return;
    }

    return runtimeConstant.value;
};

export const isStringConstant = (constant: Constants.Constant): boolean => {
    return constant?.type?.$Type === "DataTypes$StringType";
};

export const getConstantById = async (
    studioPro: StudioProApi,
    documentId: string
): Promise<Constants.Constant | undefined> => {
    if (!documentId) {
        return;
    }

    return (
        (await studioPro.app.model.constants.load<Constants.Constant>("Constants$Constant", documentId)) || undefined
    );
};
